// Verifies the X-IA-Signature header (HMAC-SHA256) so only real events from
// Instagram Automation are accepted, then builds a human-readable message.
// Requires env IA_WEBHOOK_SECRET (the signing secret shown when you created the webhook).
const crypto = require('crypto');
const secret = $env.IA_WEBHOOK_SECRET;
const out = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const body = item.json.body || {};
  if (!secret) throw new Error('IA_WEBHOOK_SECRET is not set for n8n - see docs/N8N.md');
  const ts = headers['x-ia-timestamp'];
  const signature = headers['x-ia-signature'] || '';
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + JSON.stringify(body)).digest('hex');
  const valid = signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
  if (!valid) throw new Error('Invalid webhook signature - event rejected');
  if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('Webhook timestamp too old - event rejected');

  const post = (body.data && body.data.post) || {};
  const title = post.headline || post.topic || ('Post #' + post.id);
  const texts = {
    'post.needs_review': `📝 Needs review: "${title}" ${post.review_flags ? '(⚠ ' + post.review_flags + ' item(s) to verify)' : ''}`,
    'post.approved': `✅ Approved: "${title}"`,
    'post.rejected': `❌ Rejected: "${title}"`,
    'post.scheduled': `🗓 Scheduled: "${title}" for ${post.scheduled_at}`,
    'post.published': post.published_via_mock ? `🧪 SIMULATED publish (mock mode): "${title}"` : `🎉 Published on Instagram: "${title}" ${post.instagram_permalink || ''}`,
    'post.publish_retry': `⏳ Publishing retry for "${title}": ${post.last_error}`,
    'post.failed': `🚨 Publishing FAILED for "${title}": ${post.last_error}`,
    'post.generation_failed': `⚠ AI generation failed for "${title}"`,
    'schedule.missed_slot': `⚠ Missed slot (not approved in time): "${title}"`,
    'instagram.token_expired': `🔑 Instagram connection expired - reconnect: ${body.data && body.data.settings_url}`,
    'webhook.test': '🔔 Test event received from Instagram Automation',
  };
  out.push({ json: {
    event: body.event,
    delivery_id: body.id,
    message: (texts[body.event] || body.event) + (post.dashboard_url ? `\n${post.dashboard_url}` : ''),
    post,
  }});
}
return out;
